#include "PresetManager.h"
namespace cymbalforge {
bool PresetManager::save(const juce::File& file,const CymbalEngine& engine) {
    const auto& p=engine.parameters; auto object=new juce::DynamicObject;
    auto put=[object](const char* name,const std::atomic<float>& value){object->setProperty(name,value.load());};
    put("velocity",p.velocity);put("position",p.position);put("brightness",p.brightness);put("decay",p.decay);put("choke",p.choke);put("complexity",p.complexity);put("shimmer",p.shimmer);put("noise",p.noise);put("subLevel",p.subLevel);put("subTune",p.subTune);put("subDecay",p.subDecay);put("subDelay",p.subDelay);put("filterCutoff",p.filterCutoff);put("filterResonance",p.filterResonance);put("modLfoRate",p.modLfoRate);put("modLfoDepth",p.modLfoDepth);put("reverb",p.reverb);put("gain",p.gain);
    for(int i=0;i<4;++i){auto prefix="sample"+juce::String(i+1);put((prefix+"Level").toRawUTF8(),p.sampleLevel[(size_t)i]);put((prefix+"Tune").toRawUTF8(),p.sampleTune[(size_t)i]);put((prefix+"Attack").toRawUTF8(),p.sampleAttack[(size_t)i]);put((prefix+"Release").toRawUTF8(),p.sampleRelease[(size_t)i]);put((prefix+"Delay").toRawUTF8(),p.sampleDelay[(size_t)i]);put((prefix+"LfoRate").toRawUTF8(),p.sampleLfoRate[(size_t)i]);put((prefix+"LfoDepth").toRawUTF8(),p.sampleLfoDepth[(size_t)i]);object->setProperty(prefix+"Path",engine.sampleFile(i).getFullPathName());}
    object->setProperty("modes",p.modes.load());object->setProperty("model",p.model.load());object->setProperty("filterMode",p.filterMode.load());object->setProperty("modTarget",p.modTarget.load());return file.replaceWithText(juce::JSON::toString(juce::var(object),true));
}
bool PresetManager::load(const juce::File& file,CymbalEngine& engine) {
    auto value=juce::JSON::parse(file);if(!value.isObject())return false;auto*object=value.getDynamicObject();auto&p=engine.parameters;auto get=[object](const char*name,std::atomic<float>&out){if(object->hasProperty(name))out.store(float(object->getProperty(name)));};
    get("velocity",p.velocity);get("position",p.position);get("brightness",p.brightness);get("decay",p.decay);get("choke",p.choke);get("complexity",p.complexity);get("shimmer",p.shimmer);get("noise",p.noise);get("subLevel",p.subLevel);get("subTune",p.subTune);get("subDecay",p.subDecay);get("subDelay",p.subDelay);get("filterCutoff",p.filterCutoff);get("filterResonance",p.filterResonance);get("modLfoRate",p.modLfoRate);get("modLfoDepth",p.modLfoDepth);get("reverb",p.reverb);get("gain",p.gain);
    for(int i=0;i<4;++i){auto prefix="sample"+juce::String(i+1);get((prefix+"Level").toRawUTF8(),p.sampleLevel[(size_t)i]);get((prefix+"Tune").toRawUTF8(),p.sampleTune[(size_t)i]);get((prefix+"Attack").toRawUTF8(),p.sampleAttack[(size_t)i]);get((prefix+"Release").toRawUTF8(),p.sampleRelease[(size_t)i]);get((prefix+"Delay").toRawUTF8(),p.sampleDelay[(size_t)i]);get((prefix+"LfoRate").toRawUTF8(),p.sampleLfoRate[(size_t)i]);get((prefix+"LfoDepth").toRawUTF8(),p.sampleLfoDepth[(size_t)i]);auto path=object->getProperty(prefix+"Path").toString();if(path.isNotEmpty())engine.loadSampleSlot(i,juce::File(path));}
    if(object->hasProperty("modes"))p.modes.store(int(object->getProperty("modes")));if(object->hasProperty("model"))p.model.store(int(object->getProperty("model")));if(object->hasProperty("filterMode"))p.filterMode.store(int(object->getProperty("filterMode")));if(object->hasProperty("modTarget"))p.modTarget.store(int(object->getProperty("modTarget")));return true;
}
}
